  'admin_has_rejected_your_withdraw_request  because dsgfdgvdfg' => 'لقد رفض المشرف طلب السحب الخاص بك بسبب dsgfdgvdfg',
  'admin_has_settled_your_withdraw_request' => 'قام المشرف بتسوية طلب السحب الخاص بك',
  'When creating a level  need to prioritize defining the targets before the customer uses this level and points required for a customer to achieve that level. If there is a mismatch in setting these criteria  it may affect the customer s ability to reach the level.' => 'عند إنشاء مستوى، يجب تحديد الأولوية لتحديد الأهداف قبل أن يستخدم العميل هذا المستوى والنقاط المطلوبة للعميل لتحقيق هذا المستوى. إذا كان هناك عدم تطابق في تحديد هذه المعايير فقد يؤثر ذلك على قدرة العميل على الوصول إلى المستوى.',
  'What’s priority & how it effects' => 'ما هي الأولوية وكيف تؤثر؟',
  'Using  Add New Level  the admin can create a new level for customers. To set up a new level  the admin needs to define targets and points to be earned. When a customer meets those targets and earns the required points  they will upgrade to the new level from their current one.' => 'باستخدام إضافة مستوى جديد، يمكن للمسؤول إنشاء مستوى جديد للعملاء. لإعداد مستوى جديد، يحتاج المسؤول إلى تحديد الأهداف والنقاط التي سيتم كسبها. عندما يحقق العميل هذه الأهداف ويحصل على النقاط المطلوبة، فسوف يقوم بالترقية إلى المستوى الجديد من مستواه الحالي.',
  'How to setup level' => 'كيفية إعداد المستوى',
  'When a new customer logs into the app  they start at a default level. This level helps new customers get used to the platform. As the customer completes rides and meets specific performance goals set by the admin  they can move up to the next level.' => 'عندما يقوم عميل جديد بتسجيل الدخول إلى التطبيق، فإنه يبدأ عند المستوى الافتراضي. يساعد هذا المستوى العملاء الجدد على التعود على المنصة. عندما يكمل العميل رحلاته ويحقق أهداف الأداء المحددة التي حددها المسؤول، يمكنه الانتقال إلى المستوى التالي.',
  'What’s default level' => 'ما هو المستوى الافتراضي',
