  'Enable Firebase OTP means users will not receive verification codes through Email or SMS Although those methods are activated.' => 'يعني تمكين Firebase OTP أن المستخدمين لن يتلقوا رموز التحقق عبر البريد الإلكتروني أو الرسائل النصية القصيرة على الرغم من تنشيط هذه الطرق.',
  'If you disable Firebase OTP  users will no longer receive verification codes via Firebase. You must activate Email or SMS verification as an alternative' => 'إذا قمت بتعطيل Firebase OTP، فلن يتمكن المستخدمون من تلقي رموز التحقق عبر Firebase. يجب عليك تفعيل التحقق من البريد الإلكتروني أو الرسائل النصية القصيرة كبديل',
