  'Customers see the surge fee before confirming, and drivers receive higher earnings for those trips.' => 'يرى العملاء الرسوم الزائدة قبل التأكيد، ويحصل السائقون على أرباح أعلى مقابل تلك الرحلات.',
  'When active, the surge fee is automatically added to the normal fare for rides or parcel deliveries.' => 'عند تفعيلها، تتم إضافة رسوم الزيادة تلقائيًا إلى السعر العادي للمشاوير أو توصيل الطرود.',
  'The admin manually creates a surge price rule for specific zones, vehicle types, or time periods.' => 'يقوم المسؤول يدويًا بإنشاء قاعدة زيادة الأسعار لمناطق أو أنواع مركبات أو فترات زمنية محددة.',
  'How Surge Price Work' => 'كيف يعمل ارتفاع الأسعار',
  'this_surge_price_will_be_applied_for_{count}.' => 'سيتم تطبيق هذا السعر الزائد على :count.',
  'Days Selected' => 'الأيام المختارة',
  'every_week_from_{startDate}_to_{endDate}' => 'كل أسبوع من :startDate إلى :endDate',
  'every_week_from_:startDate_to_:endDate' => 'كل أسبوع من:startDate إلى:endDate',
  'To ensure customers can still get rides or deliveries when conditions are less favorable.' => 'للتأكد من أنه لا يزال بإمكان العملاء الحصول على رحلات أو توصيلات عندما تكون الظروف أقل ملاءمة.',
  'Total {countDays} Days Applied' => 'إجمالي :countDays من الأيام المطبقة',
  'This charge is added to a ride for special conditions, such as extreme weather.' => 'تتم إضافة هذه الرسوم إلى الرحلة في ظروف خاصة، مثل الطقس القاسي.',
  'If you close now, the progress made so far will be saved. The remaining content will not be translated.' => 'إذا قمت بالإغلاق الآن، فسيتم حفظ التقدم الذي تم إحرازه حتى الآن. لن يتم ترجمة المحتوى المتبقي.',
  'Translating_may_take_up_to_{time}' => 'قد تستغرق الترجمة ما يصل إلى :time',
  'few hours' => 'ساعات قليلة',
  'To fairly compensate drivers for the extra time and effort needed in tough situations.' => 'لتعويض السائقين بشكل عادل عن الوقت الإضافي والجهد اللازم في المواقف الصعبة.',
  'Scootiasdfa Rate' => 'معدل سكوتياسدفا',
  'Why Surge Price is Needed' => 'لماذا هناك حاجة إلى ارتفاع الأسعار',
  'for example, during heavy rain, traffic jams, or other challenging conditions.' => 'على سبيل المثال، أثناء هطول الأمطار الغزيرة أو الاختناقات المرورية أو غيرها من الظروف الصعبة.',
  'Surge Price is an extra fee added to rides or parcel deliveries during high-demand or difficult times when completing a trip requires more effort from drivers' => 'السعر الزائد هو رسوم إضافية تضاف إلى الرحلات أو توصيل الطرود أثناء ارتفاع الطلب أو الأوقات الصعبة عندما يتطلب إكمال الرحلة المزيد من الجهد من السائقين',
  'What is Surge Price' => 'ما هو سعر الارتفاع',
