  'Navigate Life with Ease: Welcome to E-Ride, Your Premier Ride-Sharing Experience!' => 'تنقل الحياة بكل سهولة: مرحبًا بك في E-Ride ، تجربتك الممتازة في ركوب الركوب!',
  'Unlock a World of Convenience: Welcome to E-Ride, Your Ultimate Ride-Sharing Destination! Seamlessly Connect with Reliable Drivers, Enjoy Comfortable Journeys- One Ride at a Time.' => 'افتح عالمًا من الراحة: مرحبًا بك في E-Ride ، وجهة مشاركة الركوب النهائية! ',
  ' Experience the pinnacle of convenience with our ride service—prompt pickups, smooth journeys, and satisfaction guaranteed, all in one ride. ' => ' Experience the pinnacle of convenience with our ride service—prompt pickups, smooth journeys, and satisfaction guaranteed, all in one ride. ',
  ' Join our community of happy customers! Discover seamless experiences, personalized service, and satisfaction guaranteed. Your joy is our priority! ' => ' انضم إلى مجتمعنا من العملاء السعداء! اكتشف التجارب السلسة والخدمة الشخصية والرضا المضمون. فرحتك هي أولويتنا! ',
  'Set the maximum number of parcels delivery a driver can carry at once. Once the limit is reached, the driver cannot accept new parcel requests until existing deliveries are completed.' => 'تحديد الحد الأقصى لعدد الطرود التي يمكن للسائق حملها مرة واحدة. بمجرد الوصول إلى الحد الأقصى، لا يمكن للسائق قبول طلبات الطرود الجديدة حتى يتم الانتهاء من عمليات التسليم الحالية.',
  'Enable this, customers will gain access to level-specific features and benefits' => 'عند تمكين هذا، سيتمكن العملاء من الوصول إلى الميزات والفوائد الخاصة بالمستوى المحدد',
  'If a driver updates the details of an existing vehicle, certain changes may require admin approval.' => 'إذا قام السائق بتحديث تفاصيل مركبة موجودة، فقد تتطلب بعض التغييرات موافقة المسؤول.',
