  'available_vehicsdfdsfles_in_this_zone' => 'المركبات المتاحة في هذه المنطقة',
  'business_managsdfdsfement' => 'إدارة الأعمال',
  'If Yes, customers can add routes between pickup and destination' => 'إذا كانت الإجابة بنعم، فيمكن للعملاء إضافة مسارات بين الالتقاء والوجهة',
  'When the time is over, the requests get removed automatically.' => 'عند انتهاء الوقت، تتم إزالة الطلبات تلقائيًا.',
  'When this option is enabled, for starting the trip, the driver will need to get an OTP from the customer' => 'عند تفعيل هذا الخيار، لبدء الرحلة، سيحتاج السائق إلى الحصول على كلمة المرور لمرة واحدة (OTP) من العميل',
  'Do you want to turn ON Parcel Return Time & Fee for driver  When it’s ON, the driver need to pay parcel return delay fee. ' => 'هل ترغب في تشغيل وقت إرجاع الطرود والرسوم للسائق؟ عندما يكون قيد التشغيل، يحتاج السائق إلى دفع رسوم تأخير إرجاع الطرود. ',
  'this_time_is_the_minimum_advance_booking_time_for_scheduled_trips,_customer_cant_book_a_scheduled_trip_before_this.' => 'هذه المرة هي الحد الأدنى لوقت الحجز المسبق للرحلات المجدولة، ولا يمكن للعميل حجز رحلة مجدولة قبل ذلك.',
  'this_time_is_the_maximum_advance_booking_time_for_scheduled_trips,_customer_can_not_book_a_scheduled_trip_if_the_time_is_over.' => 'هذه المرة هي الحد الأقصى لوقت الحجز المسبق للرحلات المجدولة، ولا يمكن للعميل حجز رحلة مجدولة إذا انتهى الوقت.',
  'By default, it is set to 5 kilometers' => 'افتراضيًا، تم ضبطه على 5 كيلومترات',
  'By default, it is set to 10 meters' => 'بشكل افتراضي، يتم ضبطه على 10 أمتار',
  'Socket connection establishing URL is base url, Its is not editable' => 'عنوان URL الخاص بإنشاء اتصال المقبس هو عنوان URL الأساسي، وهو غير قابل للتحرير',
  'Do you want to turn ON Parcel Tracking Link for customer  When turned ON, customers will receive a tracking link once the parcel is confirmed.' => 'هل ترغب في تشغيل رابط تتبع الطرود للعملاء؟ عند تشغيله، سيتلقى العملاء رابط تتبع بمجرد تأكيد الطرد.',
  'Hear you can write a massage body. Customer Name, Parcel ID & Tracking link will generate automatically for each individual parcel.' => 'أسمع يمكنك كتابة تدليك الجسم. سيتم إنشاء اسم العميل ومعرف الطرد ورابط التتبع تلقائيًا لكل طرد على حدة.',
  'When the toggle is turned ON, the parcel return time and fee are activated  when turned OFF, they are deactivated.' => 'عند تشغيل مفتاح التبديل، يتم تنشيط وقت إرجاع الطرود والرسوم عند إيقاف تشغيله، ويتم إلغاء تنشيطهما.',
  'If turned ON, customer will notify if their requested weight exceeds the capacity.' => 'إذا تم تشغيله، فسيقوم العميل بإخطار ما إذا كان الوزن المطلوب يتجاوز السعة.',
  'If the toggle is turned OFF, Customer will not notify if their requested weight exceeds the capacity.' => 'إذا تم إيقاف التبديل، فلن يقوم العميل بإخطار ما إذا كان الوزن المطلوب يتجاوز السعة.',
  'Image format : jpg, png, jpeg, webp | Maximum size : 5MB' => 'تنسيق الصورة: jpg، png، jpeg، webp | الحد الأقصى للحجم: 5 ميجابايت',
  'Set minimum Android app version. If user don t have, they ll be requested a force update.' => 'قم بتعيين الحد الأدنى لإصدار تطبيق Android. إذا لم يكن المستخدم قد فعل ذلك، فسوف يُطلب منه فرض التحديث.',
  'File Format - jpg, jpeg, png, webp | Image Size - Maximum Size 5 MB.' => 'تنسيق الملف - jpg، jpeg، png، webp | حجم الصورة - الحد الأقصى للحجم 5 ميجابايت.',
  'With Firebase OTP enabled, verification codes will be sent through Firebase.' => 'مع تمكين Firebase OTP، سيتم إرسال رموز التحقق من خلال Firebase.',
  'If you disable Firebase OTP, users will no longer receive verification codes via Firebase. You must activate Email or SMS verification as an alternative' => 'إذا قمت بتعطيل Firebase OTP، فلن يتلقى المستخدمون بعد ذلك رموز التحقق عبر Firebase. يجب عليك تفعيل التحقق من البريد الإلكتروني أو الرسائل النصية القصيرة كبديل',
  'For configuring OTP in the Firebase, you must create a Firebase project first. If you haven’t created any project for your application yet, please create a project first.' => 'لتكوين OTP في Firebase، يجب عليك إنشاء مشروع Firebase أولاً. إذا لم تكن قد أنشأت أي مشروع لتطبيقك بعد، فيرجى إنشاء مشروع أولاً.',
  'From the Sign-in providers section, select the Phone option.' => 'من قسم موفري تسجيل الدخول، حدد خيار الهاتف.',
  'If there is any existing user in this level, you can not change the status' => 'إذا كان هناك أي مستخدم موجود في هذا المستوى، فلا يمكنك تغيير الحالة',
  'Setting the Stage for Rewards and Targets. Once a target is completed or fulfilled, move on to the next one' => 'تمهيد الطريق للمكافآت والأهداف. بمجرد اكتمال الهدف أو تحقيقه، انتقل إلى الهدف التالي',
  'When a new customer logs into the app, they start at a default level. This level helps new customers get used to the platform. As the customer completes rides and meets specific performance goals set by the admin, they can move up to the next level.' => 'عندما يقوم عميل جديد بتسجيل الدخول إلى التطبيق، فإنه يبدأ بالمستوى الافتراضي. يساعد هذا المستوى العملاء الجدد على التعود على المنصة. عندما يكمل العميل رحلاته ويحقق أهداف الأداء المحددة التي حددها المسؤول، يمكنه الانتقال إلى المستوى التالي.',
  'Using  Add New Level  the admin can create a new level for customers. To set up a new level, the admin needs to define targets and points to be earned. When a customer meets those targets and earns the required points, they will upgrade to the new level from their current one.' => 'باستخدام إضافة مستوى جديد، يمكن للمسؤول إنشاء مستوى جديد للعملاء. لإعداد مستوى جديد، يحتاج المسؤول إلى تحديد الأهداف والنقاط المراد كسبها. عندما يحقق العميل هذه الأهداف ويكسب النقاط المطلوبة، فسوف يقوم بالترقية إلى المستوى الجديد من المستوى الحالي.',
  'When creating a level, need to prioritize defining the targets before the customer uses this level and points required for a customer to achieve that level. If there is a mismatch in setting these criteria, it may affect the customer s ability to reach the level.' => 'عند إنشاء مستوى، يجب تحديد الأولوية لتحديد الأهداف قبل أن يستخدم العميل هذا المستوى والنقاط المطلوبة للعميل لتحقيق هذا المستوى. وفي حالة وجود عدم تطابق في تحديد هذه المعايير فقد يؤثر ذلك على قدرة العميل في الوصول إلى المستوى.',
  'At present, there is only one level available, which is the default level. When a customer logs in to the app for the first time, they will automatically be assigned the default level.' => 'في الوقت الحاضر، هناك مستوى واحد متاح فقط، وهو المستوى الافتراضي. عندما يقوم العميل بتسجيل الدخول إلى التطبيق لأول مرة، سيتم تعيين المستوى الافتراضي له تلقائيًا.',
  'At present, there is only one level available, which is the default level. When a driver logs in to the app for the first time, they will automatically be assigned the default level.' => 'في الوقت الحاضر، هناك مستوى واحد متاح فقط، وهو المستوى الافتراضي. عندما يقوم السائق بتسجيل الدخول إلى التطبيق لأول مرة، سيتم تعيين المستوى الافتراضي له تلقائيًا.',
  'Coupon already expired, You do not change this status.' => 'انتهت صلاحية القسيمة بالفعل، لا يمكنك تغيير هذه الحالة.',
