  'Want to disable referral earnings' => 'تريد تعطيل أرباح الإحالة',
  'If you disable referral earnings, customers will no longer receive rewards for referring new users' => 'إذا قمت بتعطيل أرباح الإحالة، فلن يحصل العملاء بعد الآن على مكافآت مقابل إحالة مستخدمين جدد',
  'Want to enable referral earnings' => 'تريد تمكين أرباح الإحالة',
