  'If you disable referral earnings, drivers will no longer receive rewards for referring new users' => 'إذا قمت بتعطيل أرباح الإحالة، فلن يحصل السائقون بعد الآن على مكافآت مقابل إحالة مستخدمين جدد',
  'If you enable referral earnings, drivers will be able to earn rewards by referring new users.' => 'إذا قمت بتمكين أرباح الإحالة، فسيتمكن السائقون من كسب المكافآت عن طريق إحالة مستخدمين جدد.',
  'The idle fee is applied when the driver pauses an ongoing trip.' => 'يتم تطبيق رسوم الخمول عندما يقوم السائق بإيقاف رحلة جارية مؤقتًا.',
  'Set the default currency used across your platform for pricing and transactions.' => 'قم بتعيين العملة الافتراضية المستخدمة عبر النظام الأساسي الخاص بك للتسعير والمعاملات.',
  'Want to enable driver self-registration' => 'تريد تمكين التسجيل الذاتي للسائق',
  ' If you turn on the driver self-registration, drivers can register directly. This streamlines onboarding.' => ' إذا قمت بتشغيل التسجيل الذاتي للسائق، فيمكن للسائقين التسجيل مباشرة. وهذا يبسط عملية الإعداد.',
  'If you turn on the driver verification, drivers must pass the verification process before they can start taking trips.' => 'إذا قمت بتشغيل التحقق من برنامج التشغيل، فيجب على السائقين اجتياز عملية التحقق قبل أن يتمكنوا من البدء في القيام بالرحلات.',
  'Want to disable driver self-registration' => 'تريد تعطيل التسجيل الذاتي للسائق',
  'If you turn off the driver self-registration, drivers will require an internal administrator to register their accounts.' => 'إذا قمت بإيقاف تشغيل التسجيل الذاتي للسائق، فسوف يحتاج السائقون إلى مسؤول داخلي لتسجيل حساباتهم.',
  'Want to enable driver verification' => 'تريد تمكين التحقق من برنامج التشغيل',
