  'Reason : Due to system updates or operational requirements.' => 'السبب : بسبب تحديثات النظام أو متطلبات التشغيل.',
  'Are you sure want to set same time for every day' => 'هل أنت متأكد أنك تريد تحديد نفس الوقت لكل يوم؟',
  'The available time set for the first day will be applied to all days of the week.' => 'سيتم تطبيق الوقت المتاح المحدد لليوم الأول على جميع أيام الأسبوع.',
  'Are you sure want to delete this schedule' => 'هل أنت متأكد أنك تريد حذف هذا الجدول الزمني',
  'Once deleted, this time slot will be removed from the availability schedule.' => 'بمجرد حذفها، ستتم إزالة هذه الفترة الزمنية من جدول التوفر.',
  'Availability schedule updated successfully' => 'تم تحديث جدول التوفر بنجاح',
  'Start time must be before end time' => 'يجب أن يكون وقت البدء قبل وقت الانتهاء',
  'Time slots cannot overlap on the same day' => 'لا يمكن أن تتداخل الفترات الزمنية في نفس اليوم',
  'Please provide both start and end time' => 'يرجى تقديم وقت البدء والانتهاء',
