  'Voice Message Support' => 'دعم الرسائل الصوتية',
  'Voice message support is currently disabled' => 'دعم الرسائل الصوتية معطل حاليًا',
  'When enabled, the voice option will appear on the applications chat page.' => 'عند تمكينه، سيظهر خيار الصوت في صفحة دردشة التطبيقات.',
  'Do you want to turn OFF voice message support for the applications' => 'هل تريد إيقاف دعم الرسائل الصوتية للتطبيقات',
  'Do you want to turn ON voice message support for the applications' => 'هل تريد تشغيل دعم الرسائل الصوتية للتطبيقات؟',
  'Do you want to turn OFF saved replies for the support center' => 'هل تريد إيقاف تشغيل الردود المحفوظة لمركز الدعم؟',
  'When it’s off the support center will not be able to see any saved replies.' => 'عندما يكون مركز الدعم خارج الخدمة، لن يتمكن من رؤية أي ردود محفوظة.',
  'When it’s on the support center will be able to see saved replies.' => 'عندما يكون في مركز الدعم سيكون قادرًا على رؤية الردود المحفوظة.',
  'Do you want to turn ON saved replies for the support center' => 'هل تريد تشغيل الردود المحفوظة لمركز الدعم؟',
  'Social Media' => 'وسائل التواصل الاجتماعي',
  'Social Media Login' => 'تسجيل الدخول عبر وسائل التواصل الاجتماعي',
  'Google Login' => 'تسجيل الدخول جوجل',
  'Apple Login' => 'تسجيل الدخول أبل',
  'Facebook Login' => 'تسجيل الدخول الفيسبوك',
  'Social Media Login Setup' => 'إعداد تسجيل الدخول عبر وسائل التواصل الاجتماعي',
  'Configure Social Media Setup' => 'تكوين إعداد الوسائط الاجتماعية',
  'You can use following login from Customer Login page after active check Social Media Login.' => 'يمكنك استخدام تسجيل الدخول التالي من صفحة تسجيل دخول العميل بعد التحقق النشط من تسجيل الدخول إلى وسائل التواصل الاجتماعي.',
  'Use {provider} login as your customer Social Media Login turn the switch & setup the required files.' => 'استخدم :provider تسجيل الدخول كعملاء تسجيل الدخول عبر وسائل التواصل الاجتماعي، قم بتشغيل المفتاح وإعداد الملفات المطلوبة.',
  'Get Credential Setup' => 'احصل على إعداد بيانات الاعتماد',
  'Store Bundle ID' => 'معرف حزمة المتجر',
  'Ex: Bundle ID' => 'على سبيل المثال: معرف الحزمة',
  'Store Client Secret Key' => 'تخزين المفتاح السري للعميل',
  'Ex: Client secret key' => 'على سبيل المثال: مفتاح العميل السري',
  'Google' => 'جوجل',
  'Facebook' => 'الفيسبوك',
  'Apple' => 'أبل',
  'With Social Media Login, customers can log in using social media accounts.' => 'من خلال تسجيل الدخول عبر وسائل التواصل الاجتماعي، يمكن للعملاء تسجيل الدخول باستخدام حسابات وسائل التواصل الاجتماعي.',
  'Select which social media you want for customer login' => 'حدد الوسائط الاجتماعية التي تريد تسجيل دخول العميل إليها',
  'Connect 3rd party login system from here' => 'قم بتوصيل نظام تسجيل دخول الطرف الثالث من هنا',
  'At least one social media must remain active for login. Otherwise social media login cannot work.' => 'يجب أن تظل إحدى وسائل التواصل الاجتماعي على الأقل نشطة لتسجيل الدخول. وإلا فإن تسجيل الدخول إلى وسائل التواصل الاجتماعي لا يمكن أن يعمل.',
  '{provider} is currently disabled from configure 3rd party social login options.' => ':provider معطل حاليًا من تكوين خيارات تسجيل الدخول الاجتماعي لجهة خارجية.',
  'Enabling Google Login, customers can log in to the site using their existing Gmail credentials.' => 'من خلال تمكين تسجيل الدخول إلى Google، يمكن للعملاء تسجيل الدخول إلى الموقع باستخدام بيانات اعتماد Gmail الحالية الخاصة بهم.',
  'Enabling Facebook Login, customers can log in to the site using their existing Facebook credentials.' => 'من خلال تمكين تسجيل الدخول عبر Facebook، يمكن للعملاء تسجيل الدخول إلى الموقع باستخدام بيانات اعتماد Facebook الحالية الخاصة بهم.',
  'Enabling Apple Login, customers can log in to the site using their existing Apple login credentials, Only for Apple devices.' => 'من خلال تمكين تسجيل الدخول إلى Apple، يمكن للعملاء تسجيل الدخول إلى الموقع باستخدام بيانات اعتماد تسجيل الدخول الحالية إلى Apple، فقط لأجهزة Apple.',
  'Google API Setup Instructions' => 'تعليمات إعداد واجهة برمجة تطبيقات Google',
  'Apple API Setup Instructions' => 'تعليمات إعداد واجهة برمجة تطبيقات Apple',
  'Sign in to your Apple Developer account and open Certificates, Identifiers & Profiles.' => 'قم بتسجيل الدخول إلى حساب Apple Developer الخاص بك وافتح الشهادات والمعرفات والملفات الشخصية.',
  'Copy your Team ID from the top-right of the Membership page and paste it into the Team id field.' => 'انسخ معرف الفريق الخاص بك من أعلى يمين صفحة العضوية والصقه في حقل معرف الفريق.',
  'Open Identifiers, register or select an App ID, and enable the Sign in with Apple capability.' => 'افتح المعرفات، وقم بالتسجيل أو تحديد معرف التطبيق، وقم بتمكين إمكانية تسجيل الدخول باستخدام Apple.',
  'Copy the Bundle ID of that App ID and paste it into the Store Bundle ID field.' => 'انسخ معرف الحزمة لمعرف التطبيق هذا والصقه في حقل معرف حزمة المتجر.',
  'Open Keys, create a new key with Sign in with Apple enabled, and copy its Key ID into the Store Client Secret Key field.' => 'افتح Keys، وأنشئ مفتاحًا جديدًا مع تمكين تسجيل الدخول مع Apple، وانسخ معرف المفتاح الخاص به في حقل Store Client Secret Key.',
  'Download the AuthKey file (.p8), upload it in the Choose updated file field, and store it safely as it can be downloaded only once.' => 'قم بتنزيل ملف AuthKey (.p8)، وقم بتحميله في حقل اختيار ملف محدث، وقم بتخزينه بأمان حيث يمكن تنزيله مرة واحدة فقط.',
  'Turn on the switch and click Save.' => 'قم بتشغيل المفتاح وانقر فوق "حفظ".',
  'The Bundle ID is required when Apple login is active.' => 'معرف الحزمة مطلوب عندما يكون تسجيل الدخول إلى Apple نشطًا.',
  'The Key ID is required when Apple login is active.' => 'مطلوب معرف المفتاح عندما يكون تسجيل الدخول إلى Apple نشطًا.',
  'The Team ID is required when Apple login is active.' => 'معرف الفريق مطلوب عندما يكون تسجيل الدخول إلى Apple نشطًا.',
  'The AuthKey (.p8) file is required when Apple login is active.' => 'يكون ملف AuthKey (.p8) مطلوبًا عندما يكون تسجيل الدخول إلى Apple نشطًا.',
  'The uploaded file must be a .p8 AuthKey file.' => 'يجب أن يكون الملف الذي تم تحميله عبارة عن ملف AuthKey.p8.',
  'The uploaded file is not a valid AuthKey (.p8) private key file.' => 'الملف الذي تم تحميله ليس ملف مفتاح خاص AuthKey (.p8) صالحًا.',
  'A key file has been uploaded.' => 'تم تحميل ملف المفتاح.',
  'Facebook API Setup Instructions' => 'تعليمات إعداد Facebook API',
  'Go to the Google Developers Console.' => 'انتقل إلى وحدة تحكم مطوري Google.',
  'Create a new project or select an existing project.' => 'أنشئ مشروعًا جديدًا أو اختر مشروعًا موجودًا.',
  'Click on Credentials in the left-hand menu.' => 'انقر على بيانات الاعتماد في القائمة اليسرى.',
  'Create an OAuth client ID for a web application.' => 'قم بإنشاء معرف عميل OAuth لتطبيق ويب.',
  'Enter a name for your client ID and click Create.' => 'أدخل اسمًا لمعرف العميل الخاص بك وانقر فوق "إنشاء".',
  'Enter the URL of your website as an authorized JavaScript origin.' => 'أدخل عنوان URL لموقع الويب الخاص بك باعتباره أصل JavaScript معتمدًا.',
  'Enter the callback URL as an authorized redirect URL.' => 'أدخل عنوان URL لرد الاتصال كعنوان URL لإعادة التوجيه المعتمد.',
  'Copy and paste the client ID and client secret into your application settings.' => 'انسخ والصق معرف العميل وسر العميل في إعدادات التطبيق الخاص بك.',
  'Enable the Google login option in your application settings and thoroughly test the integration before deploying it to a live environment.' => 'قم بتمكين خيار تسجيل الدخول إلى Google في إعدادات التطبيق الخاص بك واختبر التكامل بدقة قبل نشره في بيئة مباشرة.',
  'Go to apple developer page' => 'اذهب إلى صفحة مطور أبل',
  'Click here' => 'انقر هنا',
  'In the top left corner you can see the Team ID [Apple developer account name] - Team ID.' => 'في الزاوية العلوية اليسرى، يمكنك رؤية معرف الفريق [اسم حساب مطور Apple] - معرف الفريق.',
  'Click plus icon, select App IDs, then click on continue.' => 'انقر على أيقونة علامة الجمع، وحدد معرفات التطبيقات، ثم انقر على متابعة.',
  'Put a description and also identifier (identifier that used for app) and this is the Client ID.' => 'ضع وصفًا ومعرفًا أيضًا (المعرف المستخدم للتطبيق) وهذا هو معرف العميل.',
  'Click continue and download the file in device named AuthKey ID.p8 (store it safely and it is used for push notification).' => 'انقر فوق "متابعة" وقم بتنزيل الملف في الجهاز المسمى AuthKey ID.p8 (قم بتخزينه بأمان وسيتم استخدامه لإشعار الدفع).',
  'Again click plus icon, select Service IDs, then click on continue.' => 'انقر مرة أخرى على أيقونة علامة الجمع، وحدد معرفات الخدمة، ثم انقر على متابعة.',
  'Put a description and also identifier and continue.' => 'ضع وصفًا ومعرفًا أيضًا واستمر.',
  'Download the file in device named AuthKey KeyID.p8 (this is the service key ID file and also after AuthKey that is the key ID).' => 'قم بتنزيل الملف في الجهاز المسمى AuthKey KeyID.p8 (هذا هو ملف معرف مفتاح الخدمة وأيضًا بعد AuthKey الذي يمثل معرف المفتاح).',
  'Go to the Facebook Developer website.' => 'انتقل إلى موقع الفيسبوك المطور.',
  'Create a new app or select an existing app.' => 'قم بإنشاء تطبيق جديد أو حدد تطبيقًا موجودًا.',
  'Click on Add a New App or select an existing app from the dashboard.' => 'انقر فوق "إضافة تطبيق جديد" أو حدد تطبيقًا موجودًا من لوحة التحكم.',
  'Fill in the required details, such as Display Name, Contact Email, and App Purpose.' => 'املأ التفاصيل المطلوبة، مثل اسم العرض والبريد الإلكتروني لجهة الاتصال والغرض من التطبيق.',
  'Click Create App to create your app.' => 'انقر فوق إنشاء تطبيق لإنشاء تطبيقك.',
  'In the left-hand menu, click on Settings and then Basic to access your app basic settings.' => 'في القائمة اليمنى، انقر فوق "الإعدادات" ثم "أساسي" للوصول إلى الإعدادات الأساسية لتطبيقك.',
  'Scroll down to the Facebook Login section and click on Set Up to configure your Facebook login settings.' => 'قم بالتمرير لأسفل إلى قسم تسجيل الدخول إلى Facebook وانقر فوق "إعداد" لتكوين إعدادات تسجيل الدخول إلى Facebook الخاصة بك.',
  'Choose the login behavior, permissions, and other settings as per your requirements.' => 'اختر سلوك تسجيل الدخول والأذونات والإعدادات الأخرى وفقًا لمتطلباتك.',
  'Copy and paste the App ID and App Secret into your application settings.' => 'انسخ والصق معرف التطبيق وسر التطبيق في إعدادات التطبيق الخاص بك.',
  'Enable the Facebook login option in your applications settings and thoroughly test the integration before deploying it to a live environment.' => 'قم بتمكين خيار تسجيل الدخول إلى Facebook في إعدادات التطبيقات الخاصة بك واختبر التكامل بدقة قبل نشره في بيئة مباشرة.',
  'Team id' => 'معرف الفريق',
  'Ex: Team id' => 'على سبيل المثال: معرف الفريق',
